import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4];BASE=Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,v):p.write_text(json.dumps(v,indent=2)+'\n',encoding='utf-8',newline='\n')
def main():
 rows=[('R-LTA-PARENT','Original contract testing and adapter criteria','curriculum/projects/PR-T32-01.md','Original curriculum',['Complete T32 module and PR-T32-01 project','All nine PR-T32-01 criterion/task/rubric/variant records','Complete fixtures/embedded/PR-T32-01.json and assessor/legacy_depth/PR-T32-01.md'],'Actual named source read. Historical units linked but not freshly reread; no new accepted baseline claim.'),
 ('R-LTA-GCC','Coverage and sanitizer dependency boundaries','https://gcc.gnu.org/onlinedocs/gcc-15.2.0/gcc/Instrumentation-Options.html','GCC15.2.0 manual',['-fprofile-arcs and --coverage: raw counts, data files and -lgcov','-fcondition-coverage: independent Boolean effect and gcov --conditions','-fsanitize=address: instrumented bounds/lifetime checks and runtime','-fsanitize-trap=: builtin trap, libubsan dependency and supported exclusions'],'Actual primary web passages read, then matching local cached sections reread. No whole-manual inspection; no host ASLR/security change; flag availability and generated dependencies measured separately.'),
 ('R-LTA-SEND','Actual socket progress and signal containment','https://pubs.opengroup.org/onlinepubs/9799919799/functions/send.html','POSIX.1-2024 Issue8',['DESCRIPTION: locally initiated transmission, no delivery guarantee, MSG_NOSIGNAL','RETURN VALUE: accepted count or -1','ERRORS: EAGAIN/EWOULDBLOCK, EINTR before data, EPIPE and signal behavior'],'Web tool failed; private WSL urllib retrieved the actual page, and complete extracted normative send text was read. Linux socket-buffer behavior is an observation, not a POSIX capacity promise.')]
 resources=[{'id':rid,'title':title,'authors':['Original curriculum authors, GNU Project or The Open Group'],'url':url,'edition':edition,'domains':['T32'],'kind':'documentation','access':'Actual bounded source passages inspected','role':'primary','assignable':True,'reason':'Separate component contract, independent oracle, verification runtime and actual OS authority.','prerequisites':['T03','T04','T07'],'locators':loc,'inspection':{'date':'2026-10-18','method':'Actual canonical source and primary web/cache text read','scope':'; '.join(loc),'limits':limit}} for rid,title,url,edition,loc,limit in rows]
 write(BASE/'resources.json',{'schema_version':1,'resources':resources,'reference_gaps':['Exact published C17 remains inaccessible.','No fresh whole-book inspection, physical peripheral measurement or independent learner assessment.']})
 paths=['curriculum/modules/T32.md','curriculum/projects/PR-T32-01.md','fixtures/embedded/PR-T32-01.json','assessor/legacy_depth/PR-T32-01.md']
 write(BASE/'source_access.json',{'schema_version':1,'date':'2026-10-18','inspected_paths':{p:sha(ROOT/p) for p in paths},'private_source_identities':[{'path':'build/t32-sources/'+p,'sha256':sha(ROOT/'build/t32-sources'/p)} for p in ('send.html','gcc-instrumentation.html')],'actual_inspections':[{'url':r[2],'edition':r[3],'passages':r[4],'limits':r[5]} for r in rows],'original_analysis':'Four equivalent caller-storage representations, complete selected finite list histories, explicit partial-progress flow and evidence authority matrix.','limits':'Author inspection, not independent human review; selected OS/object evidence is not physical target conformance.'})
 write(BASE/'research_gate.json',{'status':'passage-inspected','domains':['T32'],'inspection_kind':'Author passage inspection only','research_input_sha256':{p.relative_to(ROOT).as_posix():sha(p) for p in (BASE/'resources.json',BASE/'source_access.json')}})
 print(json.dumps({'resources':len(resources)}))
if __name__=='__main__':main()
